#include <stdio.h>

/* entradaDoShow le a idade e o ingresso (1 = tem, 0 = nao tem) digitados
   e imprime uma linha so:
     pode entrar        -> idade de 18 para cima E ingresso 1
     compre o ingresso  -> idade de 18 para cima E ingresso 0
     menor de idade     -> idade abaixo de 18
   A leitura ja esta escrita. Falta a decisao: o if da idade por FORA e,
   dentro do bloco dele, o if do ingresso — cada um com as suas chaves. */
void entradaDoShow(void) {
    int idade = 0;
    int ingresso = 0;

    scanf("%d %d", &idade, &ingresso);

    /* escreva a decisao aqui, no lugar desta linha */
    printf("pode entrar\n");
}

