#include <stdio.h>

void entradaDoShow(void) {
    int idade = 0;
    int ingresso = 0;

    scanf("%d %d", &idade, &ingresso);

    if (idade >= 18) {
        if (ingresso == 1) {
            printf("pode entrar\n");
        } else {
            printf("compre o ingresso\n");
        }
    } else {
        printf("menor de idade\n");
    }
}
